  /* ***
  if( DEBU G4 )
    fprintf(stderr, "  in KheDrsResourceOnDayAtTime(dr %p %s, %s, drs)"
      " day_index = %d, dr->days = %d\n",
      (void *) dr, KheResourceId(dr->resource),
      KheTimeId(time), day_index, HaArrayCount(dr->days));
  *** */
