/*****************************************************************************/
/*                                                                           */
/*  KHE_COST KheDrsMonitorWeight(KHE_MONITOR m)                              */
/*                                                                           */
/*  Return the weight of m's constraint.  If this cannot be done, because    */
/*  m is NULL or m is not derived from a constraint, return 0.               */
/*                                                                           */
/*****************************************************************************/

static KHE_COST KheDrsMonitorWeight(KHE_MONITOR m)
{
  KHE_CONSTRAINT c;
  if( m == NULL )
    return 0;
  c = KheMonitorConstraint(m);
  if( c == NULL )
    return 0;
  return KheConstraintCombinedWeight(c);
}


/*****************************************************************************/
/*                                                                           */
/*  int KheDrsMonitorLargestWeightFirstCmp(const void *p1, const void *p2)   */
/*                                                                           */
/*  Comparison function for sorting monitors so that those with the          */
/*  largest weights come first.                                              */
/*                                                                           */
/*****************************************************************************/

static int KheDrsMonitorLargestWeightFirstCmp(const void *p1, const void *p2)
{
  KHE_MONITOR m1 = * (KHE_MONITOR *) p1;
  KHE_MONITOR m2 = * (KHE_MONITOR *) p2;
  KHE_COST weight1, weight2;
  weight1 = KheDrsMonitorWeight(m1);
  weight2 = KheDrsMonitorWeight(m2);
  return KheCostCmp(weight2, weight1);
}


