/*****************************************************************************/
/*                                                                           */
/*  void KheDrsPrintSearchStatistics(KHE_DRS_SOLN soln,                      */
/*    KHE_DYNAMIC_RESOURCE_SOLVER drs)                                       */
/*                                                                           */
/*  Print statistics about the search that has just ended, leading to        */
/*  new solution soln.                                                       */
/*                                                                           */
/*****************************************************************************/

static float percent(int num, int denom)
{
  return denom == 0 ? -1.0 : (float) (100 * num) / (float) denom;
}

/* ***
static int KheDrsViableSolns(KHE_DRS_SOLN_LIST soln_list,
  KHE_COST max_viable_cost)
{
  KHE_DRS_SOLN soln;  int i;
  HaArrayForEach(soln_list->solns, soln, i)
    if( soln->cost > max_viable_cost )
      break;
  return i;
}
*** */

static void KheDrsPrintSearchStatistics(KHE_DRS_SOLN soln,
  KHE_DYNAMIC_RESOURCE_SOLVER drs)
{
#if TESTING
  KHE_DRS_SOLN soln2;  KHE_DRS_DAY day;  KHE_DRS_SOLN_LIST soln_list;
  int count, rank, viable, total_count, total_rank, total_viable;
  if( DEBUG21 && !(RERUN && drs->rerun != NULL) )
  {
    /* rank and viable solutions */
    fprintf(stderr, "  %4s  %10s %10s %6s    %10s %10s %6s\n",
      "Day", "Rank", "Total", "%", "Viable", "Total", "%");
    fprintf(stderr, "%s", "  -------------------------------------------"
      "-----------------------\n");
    total_count = total_viable = total_rank = 0;
    for( soln2 = soln;  soln2->prev_soln != NULL;  soln2 = soln2->prev_soln )
    {
      day = KheDrsSolnDay(soln2, drs);
      count = KheDrsSolnListCount(day->soln_list);
      rank = soln2->sorted_rank;
      viable = KheDrsSolnListViableSolns(day->soln_list, KheDrsSolnCost(soln));
      total_count += count;
      total_rank += rank;
      total_viable += viable;
      fprintf(stderr, "  %4s  %10d %10d %6.1f    %10d %10d %6.1f\n",
	KheDrsDayId(day), rank, count, percent(rank, count),
	viable, count, percent(viable, count));
    }
    fprintf(stderr, "%s", "  -------------------------------------------"
      "-----------------------\n");
    fprintf(stderr, "  %4s  %10d %10d %6.1f    %10d %10d %6.1f\n",
      "Tot.", total_rank, total_count, percent(total_rank, total_count),
      total_viable, total_count, percent(total_viable, total_count));
  }

  if( DEBUG27 )
  {
    /* cost distributions */
    for( soln2 = soln;  soln2->prev_soln != NULL;  soln2 = soln2->prev_soln )
    {
      day = KheDrsSolnDay(soln2, drs);
      fprintf(stderr, "  %s cost distributions:\n", KheDrsDayId(day));
      soln_list = day->soln_list;
      KheDrsSolnListCostDistributionDebug(soln_list, 2, 4, stderr);
    }
  }
#endif
}

