/*****************************************************************************/
/*                                                                           */
/*  bool KheDrsOpenDayFollows(KHE_DYNAMIC_RESOURCE_SOLVER drs,               */
/*    KHE_DRS_DAY day, KHE_DRS_DAY *next_day)                                */
/*                                                                           */
/*  If there is a next open day after day, set *next_day to that day and     */
/*  return true, otherwise set *next_day to NULL and return false.           */
/*                                                                           */
/*  As a special case, if day is NULL, the next open day is taken to be the  */
/*  first open day, if there is a first open day.                            */
/*                                                                           */
/*****************************************************************************/

static bool KheDrsOpenDayFollows(KHE_DYNAMIC_RESOURCE_SOLVER drs,
  KHE_DRS_DAY day, KHE_DRS_DAY *next_day)
{
  if( day == NULL )
  {
    /* special case: following day is the first open day, if any */
    if( HaArrayCount(drs->open_days) > 0 )
      return *next_day = HaArrayFirst(drs->open_days), true;
    else
      return *next_day = NULL, false;
  }
  else
  {
    /* ordinary case */
    if( day != HaArrayLast(drs->open_days) )
      return *next_day = HaArray(drs->open_days, day->open_day_index + 1), true;
    else
      return *next_day = NULL, false;
  }
}


